/* @lc app=leetcode id=3650 lang=kotlin */ class Solution { fun minCost(n: Int, edges: Array<IntArray>): Int = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to 2 * w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { Int.MAX_VALUE }.also { it[0] = 0 }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(0, 0)) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().filter { (v, w) -> c + w < d[v] }.forEach { (v, w) -> pq.add(intArrayOf(c + w, v)).also { d[v] = c + w } } }.let { d[n - 1].let { if (it == Int.MAX_VALUE) -1 else it } } } } } }